"use strict";var WDG_TIERS=[{k:"simple",n:"Sweet and Simple",price:250,guests:12,ai:8,lite:4,decor:1,keep:[],note:"Wildflower posies, a garland on the arch, two short rows of chairs, the officiant and a quiet song."},{k:"classic",n:"Classic Romance",price:800,guests:30,ai:16,lite:6,decor:2,keep:[],note:"Roses climbing the arch, a petal-strewn aisle runner, flowers at every row, a flower girl and a page boy."},{k:"elegant",n:"Elegant Evening",price:2e3,guests:60,ai:24,lite:8,decor:3,keep:[],note:"Silk draped over the arch, candle lanterns all down the aisle, tall flower columns, sashed chairs and a harpist."},{k:"grand",n:"Grand Celebration",price:4500,guests:120,ai:32,lite:10,decor:4,keep:["wed_album"],note:"A wall of flowers behind you, lanterns hung high overhead, a long carpet, a string quartet, the photographer and a wedding album."},{k:"royal",n:"Royal Splendour",price:9e3,guests:200,ai:40,lite:12,decor:5,keep:["wed_album"],note:"A gilded arch and golden chairs, towering flower pillars and banners, an honour guard down the aisle, trumpeters and a string quartet, and the album."}];var WDG_OLD={vows:"simple",intimate:"classic",classic:"elegant",grand:"grand"};var WDG_VENUES=[{k:"chapel",n:"The Everbloom Chapel",fee:300,cap:120,where:"The Everbloom Wedding House"},{k:"garden",n:"The Everbloom Garden",fee:250,cap:80,where:"The Everbloom Wedding House"},{k:"rose",n:"The Rose Room",fee:100,cap:20,where:"The Everbloom Wedding House"},{k:"registry",n:"The Registry Office",fee:0,cap:12,where:"Hearthside Family House"},{k:"spot",n:"A place of your own choosing",fee:400,cap:200,where:"wherever you mark",note:"Anywhere in the dream: a world you love, a street in Somnucor, your own home. Stand where the arch should go, facing where your guests will sit, and mark the spot. The planners bring everything there."}];var WDG_CULTURES=[{k:"classic",n:"Classic church wedding",col:[16052456,14202976,15917798],s:"arch",rite:"rings",o:"priest",note:"White and gold, an arch of roses, the vows and the exchange of rings.",act:"The rings are brought forward on a cushion and placed on each other's hand."},{k:"civil",n:"Civil ceremony",col:[15591644,6982298,15790320],s:"table",rite:"sign",o:"registrar",note:"A simple, warm ceremony at a signing table, the vows, and both names in the register.",act:"The couple sign the register, and two guests sign as witnesses."},{k:"celtic",n:"Celtic handfasting",col:[15262412,4090426,15788224],s:"willow",rite:"cord",o:"druid",note:"A willow arch tied with ribbons; the couple's hands are bound with a cord: tying the knot.",act:"The couple's joined hands are bound with a braided cord: the knot is tied."},{k:"moon",n:"Moon handfasting, the Old Ways",col:[1709602,13159640,9071288],s:"circle",rite:"cord",o:"priestess",note:"A ring of candles under a silver moon arch, the four quarters called, and hands bound with a cord.",act:"The four quarters are called, and the couple's hands are bound with a silver cord."},{k:"jewish",n:"Jewish wedding under the chuppah",col:[16052972,2771594,16777215],s:"chuppah",rite:"glass",o:"rabbi",note:"A canopy on four poles, the seven blessings, and the glass broken underfoot. Mazel tov!",act:"The seven blessings are said, a glass is wrapped in cloth and broken underfoot, and everyone calls Mazel tov!"},{k:"hindu",n:"Hindu wedding in the mandap",col:[13117982,15251504,15769632],s:"mandap",rite:"fire",o:"pandit",note:"A pillared mandap of marigolds, the sacred fire, the exchange of garlands and the seven steps.",act:"Garlands are exchanged, and the couple take the seven steps around the sacred fire, a vow at each."},{k:"muslim",n:"Muslim nikah",col:[15921386,3041866,16184032],s:"arches",rite:"scroll",o:"imam",note:"Arches in white and green, a reading, the mahr (the gift) and the offer and acceptance said before witnesses.",act:"The mahr is named, the offer and acceptance are spoken before two witnesses, and the contract is signed."},{k:"chinese",n:"Chinese tea ceremony",col:[12590622,15253576,16042184],s:"redgate",rite:"tea",o:"teamaster",note:"Red and gold, the double happiness sign and lanterns; the couple serve tea to their elders.",act:"The couple kneel and serve tea to their elders, who bless them and give red envelopes."},{k:"shinto",n:"Shinto wedding",col:[16184560,13120542,15915232],s:"torii",rite:"sake",o:"kannushi",note:"A vermilion torii gate, purification, and the three times three sips of sake (san-san-kudo).",act:"The couple share sake from three cups, three sips each: san-san-kudo."},{k:"yoruba",n:"Yoruba wedding",col:[15253552,2779706,13122154],s:"canopy",rite:"tasting",o:"elder",note:"A rich canopy, matching family colours, and the tasting of the elements: kola, honey, pepper and water.",act:"The couple taste the four elements: kola nut for long life, honey for sweetness, pepper for passion, water for purity."},{k:"greek",n:"Greek Orthodox crowning",col:[16052454,13148224,16777215],s:"iconstand",rite:"crowns",o:"orthodox",note:"The stefana: two crowns joined by a ribbon, the common cup, and the dance of Isaiah round the table.",act:"The crowns joined by a ribbon are set on the couple's heads and exchanged three times, and they walk round the table three times."},{k:"norse",n:"Norse handfasting",col:[6969924,12099696,15261896],s:"runestones",rite:"sword",o:"gothi",note:"Standing stones and a ring of torches, the ancestral sword and the rings exchanged upon its hilt.",act:"The ancestral sword is passed, and the rings are given upon its hilt."}];var WDG_OFFICIANTS=[{k:"priest",n:"Father Ambrose Hale",t:"a parish priest",sex:"m",age:62,dress:{top:16052972,topKind:"robe",bottom:1710622},acc:["stole:0xD8B860"]},{k:"minister",n:"Reverend Clara Whitlow",t:"a minister",sex:"f",age:48,dress:{top:1447450,topKind:"robe",bottom:1447450},acc:["collar","stole:0x6A2A3A"]},{k:"registrar",n:"Horace Pennywhistle",t:"the registrar of Somnucor",sex:"m",age:58,dress:{top:15262938,layer:"suit",layerColor:2764346,bottom:2764346},acc:[]},{k:"celebrant",n:"Juniper Vale",t:"an independent celebrant who leads any kind of wedding",sex:"f",age:39,dress:{top:5925514,layer:"suit",layerColor:3820138,bottom:2764864},acc:[]},{k:"druid",n:"Bran Ashgrove",t:"a Celtic druid celebrant",sex:"m",age:55,dress:{top:15657696,topKind:"robe",bottom:15657696,hat:"hood",hatColor:4090426},acc:[]},{k:"priestess",n:"High Priestess Selene Morrow",t:"High Priestess of the Obsidian Moon",sex:"f",age:46,dress:{top:1314840,topKind:"robe",bottom:1314840},acc:["circlet"]},{k:"rabbi",n:"Rabbi Eliezer Stern",t:"a rabbi",sex:"m",age:60,dress:{top:15790320,layer:"suit",layerColor:1710626,bottom:1710626},acc:["kippah","tallit"]},{k:"pandit",n:"Pandit Raghav Sharma",t:"a Hindu priest (pandit)",sex:"m",age:57,dress:{top:15919312,topKind:"robe",bottom:15919312},acc:["stole:0xE89020","tilak"]},{k:"imam",n:"Imam Yusuf Haddad",t:"an imam",sex:"m",age:52,dress:{top:16184558,topKind:"robe",bottom:16184558},acc:["kufi"]},{k:"teamaster",n:"Madam Lin Mei",t:"mistress of ceremonies for the tea ceremony",sex:"f",age:61,dress:{top:12066334,topKind:"robe",bottom:12066334},acc:["stole:0xE8C048"]},{k:"kannushi",n:"Kannushi Haruki Sato",t:"a Shinto priest (kannushi)",sex:"m",age:59,dress:{top:16316660,topKind:"robe",bottom:6961802},acc:["eboshi"]},{k:"elder",n:"Alaga Adunni Bello",t:"the alaga, the Yoruba mistress of ceremonies",sex:"f",age:54,dress:{top:2779706,topKind:"robe",bottom:2779706},acc:["gele:0xE8C030","stole:0xE8C030"]},{k:"orthodox",n:"Father Nikolaos Petrakis",t:"a Greek Orthodox priest",sex:"m",age:64,dress:{top:1315860,topKind:"robe",bottom:1315860},acc:["kamilavkion","stole:0xD8B040"]},{k:"gothi",n:"Gothi Ingrid Halvarsdottir",t:"a gothi, a Norse priestess and celebrant",sex:"f",age:50,dress:{top:6969924,topKind:"robe",bottom:4865584},acc:["fur","circlet"]}];var WDG_WORDS={classic:["Dearly beloved, we are gathered here together to join {A} and {B} in marriage.","Marriage is a promise made with an open heart: to love, to honour and to cherish, in good times and in hard.","If anyone here knows a reason these two may not be joined, let them speak now, or forever hold their peace.","{A} and {B}, you come freely and with full hearts. Please join hands.","These rings are a circle without end. Give them now as a sign of your love.","Then let each of you answer: will you take each other, from this day forward?"],civil:["Welcome, everyone. We are here to witness the marriage of {A} and {B}.","This is a civil ceremony: no grand words are needed, only true ones.","I am bound to ask: do you know of any lawful reason why you may not marry? Then we may go on.","Before these witnesses, please each say the words that make it so.","After your vows you will sign the register, and two of your guests will sign as witnesses.","{A}, {B}: are you ready to make your declaration?"],celtic:["Welcome, friends, beneath the willow. We gather in the old way to see {A} and {B} handfasted.","Join your hands, right to right and left to left, so your arms make the sign of forever.","With this cord I bind you: not to hold you captive, but to show the bond you have chosen freely.","The first turn for friendship, the second for faithfulness, the third for joy that lasts.","So the knot is tied, and from it comes the old saying: you have tied the knot.","Now speak your promises, and let them be heard by the earth and the sky."],moon:["Welcome, all, within the circle. The candles are lit and the moon looks down.","I call to the East and the air, to the South and the fire, to the West and the water, to the North and the earth: witness us.","{A} and {B} come of their own free will to be handfasted under the Old Ways.","Join your hands. With this silver cord I bind your hands, as your hearts are already bound.","As long as love shall last, may you walk together in light and in shadow.","Speak now your vows, and let the circle hear them."],jewish:["Welcome, all. Beneath this chuppah, open on every side like the tent of Abraham, {A} and {B} begin their home.","The chuppah has no walls, for a home is built on welcome, and its roof is love.","We say over you the seven blessings: for joy and gladness, for love and companionship, for peace and friendship.","Blessed are you who gladdens the couple, and who makes this love a blessing to all who know it.","Now the glass is wrapped and broken underfoot: even in our greatest joy we remember, and we begin. Mazel tov!","{A}, {B}: speak your promise to one another."],hindu:["Namaste, and welcome. Before the sacred fire, Agni, the witness of all vows, {A} and {B} are joined.","First the garlands, the jaimala: each places a garland on the other, and so each is welcomed.","Now the knot is tied between your scarves, the gathbandhan, and you take the seven steps around the fire.","With the first step, nourishment; the second, strength; the third, prosperity; the fourth, happiness.","The fifth, children and family; the sixth, long life together; and the seventh, lifelong friendship.","Having walked the seven steps, speak your vows before the fire."],muslim:["Bismillah. Welcome, all, to the nikah of {A} and {B}.","Marriage is a covenant of tranquillity, love and mercy between two people.","The mahr, the gift, has been named and is given gladly.","Before these two witnesses, the offer is made, and it must be accepted freely, and said three times.","May your home be filled with peace, patience and kindness all your days.","Now speak your acceptance, and let the witnesses hear it."],chinese:["Welcome, honoured family and friends, to the tea ceremony of {A} and {B}.","The double happiness sign shines over you: happiness for one, and happiness for two.","Now the couple kneel and serve tea to their elders: first to the parents, then to the grandparents, aunts and uncles.","Each elder drinks and gives a blessing, and a red envelope for good fortune.","Tea is a promise of respect: to honour family, and to be honoured by it.","With the elders' blessing, speak your vows to one another."],shinto:["Welcome. Before the kami, {A} and {B} come to be joined.","First, purification: may every worry be swept away like leaves before the wind.","Now san-san-kudo: three cups of sake, three sips from each. Three times three, for a bond that cannot be broken.","Each sip is a promise: to love, to share hardship, and to share joy.","The sacred branch, the tamagushi, is offered, and the kami are thanked.","Now read your vows before the kami and your families."],yoruba:["E kaabo! Welcome, families and friends, to the joining of {A} and {B}.","Today two families become one, dressed alike in their chosen colours.","Now the tasting of the elements: kola nut for long life, honey for sweetness, pepper for passion, and water for purity.","Taste each, and remember: a marriage holds the sweet and the hot together, and is washed new each day.","The elders bless you: may your home be full and your laughter loud.","Now speak your promises, and let the drums answer!"],greek:["Welcome, all. In the Orthodox way, {A} and {B} are crowned as king and queen of their own home.","The rings are blessed and exchanged three times: in the name of the Father, the Son and the Holy Spirit.","Now the stefana, two crowns joined by a ribbon, are placed upon their heads and exchanged three times.","They drink from the common cup: from this day, all is shared.","Now they walk three times round the table, their first steps together as one.","Let them now say their vows before all of you."],norse:["Hail and welcome, kin and friends! Within these stones and torches, {A} and {B} are joined.","We honour those who came before, whose names we carry.","Here is the ancestral sword, passed to show that the family's strength and protection go with this union.","Upon its hilt the rings are given: a promise as strong as iron and as lasting as stone.","Join your hands, and let the old words be spoken over you.","Speak now your oath, and let the gods and your kin bear witness!"]};if(typeof module!=="undefined"&&module.exports)mo